/**
  * Tokenizer module for converting various input types to standardized string tokens.
  *
  * This module demonstrates Scala's type system with:
  * - Sealed traits for ADTs with exhaustiveness checking
  * - Case classes for immutable data structures
  * - Type classes for ad-hoc polymorphism
  * - Variance annotations (covariance/contravariance)
  * - Option type for null safety
  * - Generic type constraints
  */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.{Try, Success, Failure}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
    * Return new token with additional metadata.
    */
  def withMetadata(kvPairs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kvPairs.toMap)
  }
}

case class MutableTokenBatch(
  private var tokens: List[Token] = List.empty,
  private var _processed: Boolean = false
) {
  /**
    * Add a token to the batch.
    * @throws RuntimeException if batch is already processed
    */
  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: List[Token] = tokens

  def isProcessed: Boolean = _processed
}

// ============================================================================
// Traits (Protocol equivalents)
// ============================================================================

/**
  * Any object that can be converted to a token string.
  */
trait Tokenizable {
  def toToken: String
}

/**
  * Any object with a length.
  */
trait HasLength {
  def length: Int
}

/**
  * Contravariant processor that consumes tokens.
  */
trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
  * Covariant container - can return subtypes.
  */
class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T] = _items

  def mapTokens[R](func: T => R): List[R] = {
    _items.map(func).toList
  }
}

/**
  * Contravariant sink - can accept supertypes.
  */
class TokenSink[-T] {
  private var _received: List[Any] = List.empty

  def receive(item: T): Unit = {
    _received = _received :+ item
  }

  def drain(): List[Any] = {
    val result = _received
    _received = List.empty
    result
  }
}

/**
  * Invariant handler - exact type matching required.
  */
class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
  * Abstract base tokenizer with generic input type.
  */
abstract class BaseTokenizer[T] {
  /**
    * Convert value to token.
    */
  def tokenize(value: T): Token

  /**
    * Lazy tokenization of multiple values.
    */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
  * Tokenizer for String and Array[Byte] types.
  */
class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: Option[String => String] = None
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(str) => str
      case Right(bytes) => new String(bytes, encoding)
    }

    val normalized = normalizer.map(_(strValue)).getOrElse(strValue)
    Token(normalized, TokenType.String)
  }

  /**
    * Overloaded method for String input.
    */
  def tokenize(value: String): Token = tokenize(Left(value))

  /**
    * Overloaded method for byte array input.
    */
  def tokenize(value: Array[Byte]): Token = tokenize(Right(value))
}

/**
  * Tokenizer for numeric types with precision handling.
  */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Int, Either[Double, BigDecimal]]] {

  def tokenize(value: Either[Int, Either[Double, BigDecimal]]): Token = {
    val (strValue, typeName) = value match {
      case Left(intValue) =>
        (intValue.toString, "Int")
      case Right(Left(doubleValue)) =>
        (f"$doubleValue%.${precision}f", "Double")
      case Right(Right(decimalValue)) =>
        (decimalValue.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString, "BigDecimal")
    }

    Token(strValue, TokenType.Numeric, Map("original_type" -> typeName))
  }

  /**
    * Overloaded methods for specific numeric types.
    */
  def tokenize(value: Int): Token = tokenize(Left(value))
  def tokenize(value: Double): Token = tokenize(Right(Left(value)))
  def tokenize(value: BigDecimal): Token = tokenize(Right(Right(value)))
}

/**
  * Tokenizer for date/time types.
  */
class TemporalTokenizer(
  formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatted = value match {
      case Left(dateTime) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(isoFormat)
        dateTime.format(fmt)
      case Right(date) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(dateFormat)
        date.format(fmt)
    }

    Token(formatted, TokenType.Temporal)
  }

  /**
    * Overloaded methods for specific temporal types.
    */
  def tokenize(value: LocalDateTime): Token = tokenize(Left(value))
  def tokenize(value: LocalDate): Token = tokenize(Right(value))
}

// ============================================================================
// Advanced: Universal Tokenizer
// ============================================================================

/**
  * Tokenizer that handles multiple types with method overloading.
  */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
    * Tokenize String values.
    */
  def tokenize(value: String): Token = {
    stringTokenizer.tokenize(value)
  }

  /**
    * Tokenize byte array values.
    */
  def tokenize(value: Array[Byte]): Token = {
    stringTokenizer.tokenize(value)
  }

  /**
    * Tokenize Int values.
    */
  def tokenize(value: Int): Token = {
    numericTokenizer.tokenize(value)
  }

  /**
    * Tokenize Double values.
    */
  def tokenize(value: Double): Token = {
    numericTokenizer.tokenize(value)
  }

  /**
    * Tokenize BigDecimal values.
    */
  def tokenize(value: BigDecimal): Token = {
    numericTokenizer.tokenize(value)
  }

  /**
    * Tokenize LocalDateTime values.
    */
  def tokenize(value: LocalDateTime): Token = {
    temporalTokenizer.tokenize(value)
  }

  /**
    * Tokenize LocalDate values.
    */
  def tokenize(value: LocalDate): Token = {
    temporalTokenizer.tokenize(value)
  }

  /**
    * Tokenize Tokenizable objects.
    */
  def tokenize(value: Tokenizable): Token = {
    Token(value.toToken, TokenType.Structured)
  }

  /**
    * Handle Option values (None case).
    */
  def tokenize(value: Option[_]): Token = value match {
    case None => Token("NULL", TokenType.Null)
    case Some(v) => tokenizeAny(v)
  }

  /**
    * Fallback for Any type - uses toString.
    */
  def tokenizeAny(value: Any): Token = value match {
    case null => Token("NULL", TokenType.Null)
    case t: Tokenizable => Token(t.toToken, TokenType.Structured)
    case s: String => tokenize(s)
    case b: Array[Byte] => tokenize(b)
    case i: Int => tokenize(i)
    case d: Double => tokenize(d)
    case bd: BigDecimal => tokenize(bd)
    case dt: LocalDateTime => tokenize(dt)
    case ld: LocalDate => tokenize(ld)
    case other => Token(other.toString, TokenType.String, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
  * Registry with complex nested generic types.
  */
class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]] = List.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry = _registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers = _handlers :+ handler
  }

  /**
    * Process all items in a container through all handlers.
    */
  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.iterator
            .map(_(item))
            .find(_.isDefined)
            .getOrElse(None)
        }.toList
    }
  }
}

// ============================================================================
// Functor and Monad Patterns
// ============================================================================

/**
  * Functor for tokens with map and flatMap operations.
  */
class TokenFunctor[T](private val _value: T) {
  def map[R](func: T => R): TokenFunctor[R] = {
    new TokenFunctor(func(_value))
  }

  def flatMap[R](func: T => TokenFunctor[R]): TokenFunctor[R] = {
    func(_value)
  }

  def getOrElse(default: T): T = {
    if (_value != null) _value else default
  }

  def getValue: T = _value
}

/**
  * Extended monad operations.
  */
class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[R](funcWrapped: TokenMonad[T => R]): TokenMonad[R] = {
    new TokenMonad(funcWrapped.getValue(this.getValue))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
  * Recursive JSON value representation.
  */
sealed trait JsonValue

object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(values: List[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue
}

/**
  * Tokenizer for JSON structures with recursive types.
  */
class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  /**
    * Convert JsonValue to JSON string representation.
    */
  private def toJsonString(value: JsonValue): String = value match {
    case JsonString(s) => s""""$s""""
    case JsonNumber(n) => n.toString
    case JsonBoolean(b) => b.toString
    case JsonNull => "null"
    case JsonArray(values) =>
      val elements = values.map(toJsonString).mkString(", ")
      s"[$elements]"
    case JsonObject(fields) =>
      val pairs = fields.map { case (k, v) => s""""$k": ${toJsonString(v)}""" }.mkString(", ")
      s"{$pairs}"
  }

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) {
      // Simple pretty printing (could be enhanced with proper indentation)
      toJsonString(value)
    } else {
      toJsonString(value)
    }

    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  /**
    * Extract and tokenize a value at a JSON path.
    */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def navigate(current: JsonValue, remainingPath: List[String]): Option[JsonValue] = {
      (current, remainingPath) match {
        case (v, Nil) => Some(v)
        case (JsonObject(fields), key :: rest) =>
          fields.get(key).flatMap(navigate(_, rest))
        case (JsonArray(values), index :: rest) if index.forall(_.isDigit) =>
          val idx = index.toInt
          if (idx >= 0 && idx < values.length) {
            navigate(values(idx), rest)
          } else {
            None
          }
        case _ => None
      }
    }

    navigate(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
  * Basic tokenizer that splits text by whitespace.
  */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  /**
    * Process a single word into a token string.
    */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength match {
      case Some(max) if processed.length > max =>
        processed = processed.take(max)
      case _ =>
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
    * Split text by whitespace and return list of tokens.
    */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
    * Split text by whitespace and return list of token strings.
    */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  /**
    * Tokenize text and return tokens with character positions.
    */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+")
    var currentPos = 0
    val result = List.newBuilder[(String, Int, Int)]

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.result()
  }

  /**
    * Return the number of tokens in the text.
    */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
  * Fluent builder for creating tokenizers.
  */
class TokenizerBuilder[T] {
  private var normalizers: List[String => String] = List.empty
  private var validators: List[T => Boolean] = List.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(kvPairs: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kvPairs.toMap
    this
  }

  /**
    * Build the final tokenizer function.
    */
  def build(): T => Token = {
    val capturedNormalizers = normalizers
    val capturedValidators = validators
    val capturedMetadata = metadata

    (value: T) => {
      // Validate
      for (validator <- capturedValidators) {
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- capturedNormalizers) {
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, capturedMetadata)
    }
  }
}

// ============================================================================
// Companion Objects and Factory Methods
// ============================================================================

object Token {
  /**
    * Create a token from a Tokenizable object.
    */
  def fromTokenizable(value: Tokenizable): Token = {
    Token(value.toToken, TokenType.Structured)
  }
}

object BaseTokenizer {
  /**
    * Create a string tokenizer.
    */
  def forStrings(encoding: String = "UTF-8", normalizer: Option[String => String] = None): StringTokenizer = {
    new StringTokenizer(encoding, normalizer)
  }

  /**
    * Create a numeric tokenizer.
    */
  def forNumbers(precision: Int = 6): NumericTokenizer = {
    new NumericTokenizer(precision)
  }

  /**
    * Create a temporal tokenizer.
    */
  def forDates(format: Option[String] = None): TemporalTokenizer = {
    new TemporalTokenizer(format)
  }
}

