    */
  def tokenize(value: Int): Token = {
    numericTokenizer.tokenize(value)
  }

  /**
    * Tokenize Double values.
    */
  def tokenize(value: Double): Token = {
    numericTokenizer.tokenize(value)
  }

  /**
    * Tokenize BigDecimal values.
    */
  def tokenize(value: BigDecimal): Token = {
    numericTokenizer.tokenize(value)
  }

  /**
    * Tokenize LocalDateTime values.
    */
  def tokenize(value: LocalDateTime): Token = {
    temporalTokenizer.tokenize(value)
  }

  /**
    * Tokenize LocalDate values.
    */
  def tokenize(value: LocalDate): Token = {
    temporalTokenizer.tokenize(value)
  }

  /**
    * Tokenize Tokenizable objects.
    */
  def tokenize(value: Tokenizable): Token = {
    Token(value.toToken, TokenType.Structured)
  }

  /**
    * Handle Option values (None case).
    */
  def tokenize(value: Option[_]): Token = value match {
    case None => Token("NULL", TokenType.Null)
    case Some(v) => tokenizeAny(v)
  }

  /**
    * Fallback for Any type - uses toString.
    */
  def tokenizeAny(value: Any): Token = value match {
    case null => Token("NULL", TokenType.Null)
    case t: Tokenizable => Token(t.toToken, TokenType.Structured)
    case s: String => tokenize(s)
    case b: Array[Byte] => tokenize(b)
    case i: Int => tokenize(i)
    case d: Double => tokenize(d)
    case bd: BigDecimal => tokenize(bd)
    case dt: LocalDateTime => tokenize(dt)
    case ld: LocalDate => tokenize(ld)
    case other => Token(other.toString, TokenType.String, Map("fallback" -> true))
  }
}

