/**
  * Recursive JSON value representation.
  */
sealed trait JsonValue

object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(values: List[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue
}

/**
  * Tokenizer for JSON structures with recursive types.
  */
class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  /**
    * Convert JsonValue to JSON string representation.
    */
  private def toJsonString(value: JsonValue): String = value match {
    case JsonString(s) => s""""$s""""
    case JsonNumber(n) => n.toString
    case JsonBoolean(b) => b.toString
    case JsonNull => "null"
    case JsonArray(values) =>
      val elements = values.map(toJsonString).mkString(", ")
      s"[$elements]"
    case JsonObject(fields) =>
      val pairs = fields.map { case (k, v) => s""""$k": ${toJsonString(v)}""" }.mkString(", ")
      s"{$pairs}"
  }

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) {
      // Simple pretty printing (could be enhanced with proper indentation)
      toJsonString(value)
    } else {
      toJsonString(value)
    }

    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  /**
    * Extract and tokenize a value at a JSON path.
    */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def navigate(current: JsonValue, remainingPath: List[String]): Option[JsonValue] = {
      (current, remainingPath) match {
        case (v, Nil) => Some(v)
        case (JsonObject(fields), key :: rest) =>
          fields.get(key).flatMap(navigate(_, rest))
        case (JsonArray(values), index :: rest) if index.forall(_.isDigit) =>
          val idx = index.toInt
          if (idx >= 0 && idx < values.length) {
            navigate(values(idx), rest)
          } else {
            None
          }
        case _ => None
      }
    }

    navigate(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
  * Basic tokenizer that splits text by whitespace.
  */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  /**
    * Process a single word into a token string.
    */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength match {
      case Some(max) if processed.length > max =>
        processed = processed.take(max)
      case _ =>
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
    * Split text by whitespace and return list of tokens.
    */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
    * Split text by whitespace and return list of token strings.
    */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  /**
    * Tokenize text and return tokens with character positions.
    */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+")
    var currentPos = 0
    val result = List.newBuilder[(String, Int, Int)]

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.result()
  }

  /**
    * Return the number of tokens in the text.
    */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
  * Fluent builder for creating tokenizers.
  */
class TokenizerBuilder[T] {
  private var normalizers: List[String => String] = List.empty
  private var validators: List[T => Boolean] = List.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(kvPairs: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kvPairs.toMap
    this
  }

  /**
    * Build the final tokenizer function.
    */
  def build(): T => Token = {
    val capturedNormalizers = normalizers
    val capturedValidators = validators
    val capturedMetadata = metadata

    (value: T) => {
      // Validate
      for (validator <- capturedValidators) {
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- capturedNormalizers) {
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, capturedMetadata)
    }
  }
}

